import contextlib
import logging
import os
import re
from zipfile import ZipFile
from logging.handlers import RotatingFileHandler

logging_path = os.getcwd()
log_basename = "ue_proxy"
active_dev_loggers = set()
active_log_files = set()
active_log_handlers = {}  # key: logger-name, value: list of handlers added by this lib
main_log_handler = None

# need new log level, below debug
RAW_DATA = 5

CONSOLE_FORMAT = '%(asctime)s  %(name)-36s  %(levelname)-10s  %(message)s'
CONSOLE_FORMAT_MIN = '%(levelname)-10s  %(message)s'
FILE_FORMAT = '%(asctime)s %(levelname)-8s %(device_id)25s |%(message)s'
FILE_FORMAT_PRX = '%(asctime)s %(layer)3.3s %(levelname)-8s %(funcName)40s() #%(lineno)3d [%(proxy_id)3s] %(message)s'
RAWFILE_FORMAT = '%(asctime)s %(proxy_id)3s |%(message)s'
UE_FILE_FORMAT = '%(asctime)s %(layer)3.3s %(levelname)-8s [%(proxy_id)3s] |%(message)s'
debug_console = False


class UserKeysExtendedFormatter(logging.Formatter):
    """Library developer may need additional info to help in troubleshooting"""
    def __init__(self, user_keys, user_fmt):
        """Initialize base class with format string containing %(<key>)s where <key> comes from user_keys list"""
        self.user_keys = user_keys
        super().__init__(fmt=user_fmt)

    def format(self, record):
        """Ensure log record has all .<key> to allow for "%(<key>)s" in format string"""
        for u_key in self.user_keys:
            if not hasattr(record, u_key):
                setattr(record, u_key, "")
        line = super().format(record)
        return line


class LoggerAdapter4EmptyExtra(logging.LoggerAdapter):
    """An adapter that fills 'extra' key passed to log records but doesn't overwrite existing extra subkeys."""

    def process(self, msg, kwargs):
        """
        Process the logging message and keyword arguments passed in to
        a logging call to insert contextual information.
        If such information already exists it is not overwritten.
        """
        if 'extra' not in kwargs:
            kwargs["extra"] = self.extra
        else:
            for update_key in self.extra:
                if update_key not in kwargs["extra"]:
                    kwargs["extra"][update_key] = self.extra[update_key]
        return msg, kwargs

    def log(self, level, msg, *args, **kwargs):
        """
        Allow stacking LoggerAdapters.
        Such stacked adapters perform their process() in stacking order
        """
        if self.isEnabledFor(level):
            logger_adapter = self
            max_adapters_nesting_level = 2
            nesting_level = 0
            while isinstance(logger_adapter, logging.LoggerAdapter):
                msg, kwargs = logger_adapter.process(msg, kwargs)
                nesting_level += 1
                if nesting_level > max_adapters_nesting_level:
                    err_msg = "Exceeded nesting level of LoggerAdapters - processing not finished for"
                    self.logger._log(logging.ERROR, f"{err_msg} msg={msg}, kwargs={kwargs}", args, **kwargs)
                    return
                logger_adapter = logger_adapter.logger
            self.logger._log(level, msg, args, **kwargs)


class DynamicPropagationLogger(logging.Logger):
    """Logger that dynamically decides if propagate based on LogRecord"""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._default_propagator = lambda record: self.propagate
        self._propagator = self._default_propagator  # keep default functionality of base class

    findCaller = logging.Logger.findCaller

    def set_propagator(self, propagator):
        """
        Change propagation logic to the one specified by propagator callable having logic like:

        def propagator(record):
            return should_propagate(record)  # True (do propagate), False (stop propagation)

        :param propagator: callable with single parameter being LogRecord
        """
        self._propagator = propagator

    def remove_propagator(self, propagator):
        """Change propagation logic to default one"""
        self._propagator = self._default_propagator

    def should_propagate(self, record):
        """Query propagation logic"""
        return self._propagator(record)

    def handle(self, record):
        """Call the handlers for the specified record."""
        old_propagation = self.propagate
        try:
            self.propagate = self.should_propagate(record)
            super().handle(record)
        finally:
            self.propagate = old_propagation


@contextlib.contextmanager
def dynamic_propagation_logger():
    current_logger_class = logging.getLoggerClass()
    logging.setLoggerClass(DynamicPropagationLogger)
    yield
    logging.setLoggerClass(current_logger_class)


def create_logger(base_logger_name='ue_proxy', console_loglevel=logging.INFO):
    with dynamic_propagation_logger():
        main_logger = logging.getLogger(base_logger_name)
    main_logger.setLevel(RAW_DATA)  # filtering is on handler level, not log level
    logging.addLevelName(RAW_DATA, "RAWDATA")

    # all INFO, WARNING, ERROR, CRITICAL should always go to CONSOLE

    if not debug_console:
        cfh = _create_console_handler(loglevel=console_loglevel, fmt=CONSOLE_FORMAT_MIN)
        _add_logger_handler(logger=main_logger, handler=cfh)

    return main_logger


def _add_logger_handler(logger, handler):
    if logger.name not in active_log_handlers:
        active_log_handlers[logger.name] = [handler]
        logger.addHandler(handler)
    elif handler not in active_log_handlers[logger.name]:  # don't add same handler multiple times
        active_log_handlers[logger.name].append(handler)
        logger.addHandler(handler)


def convert_logging_level(logging_level):
    """From string value into logging module value"""
    map2logging_level = {'CRITICAL': logging.CRITICAL,
                         'ERROR': logging.ERROR,
                         'WARNING': logging.WARNING,
                         'INFO': logging.INFO,
                         'DEBUG': logging.DEBUG,
                         'NOTSET': logging.NOTSET}
    logging_loglevel = map2logging_level.get(logging_level, logging.INFO)
    return logging_loglevel


def change_mainlog_loglevel(logging_level: str):
    if main_log_handler:
        logging_loglevel = convert_logging_level(logging_level)
        main_log_handler.setLevel(logging_loglevel)


def _remove_logs(logs_directory):
    logs_dir_content = os.listdir(logs_directory)
    for filename in logs_dir_content:
        if filename.endswith(".log"):
            os.remove(os.path.join(logs_directory, filename))


def zipp_logs(zip_name, log_dir=None, logger=None, skip_files_pattern=r''):
    _log_dir = log_dir if log_dir else logging_path
    _logger = logger if logger else logging.getLogger('ue_proxy')
    _logger.info(f"creating {zip_name}")
    # TODO: refactor to async zipping to not block proxy on zipping large logs
    #       but rather async-write by chunks
    zipped = []
    with ZipFile(zip_name, "w") as zipped_log:
        for filename in os.listdir(_log_dir):
            if skip_files_pattern and re.findall(skip_files_pattern, filename):
                continue
            if not filename.endswith(".log"):
                continue
            path = os.path.relpath(os.path.join(_log_dir, filename))
            if os.path.isfile(path):
                zipped.append(filename)
                zipped_log.write(path)
    _logger.info(f"created {zip_name} containing {zipped}")
    return zipped


@contextlib.asynccontextmanager
async def zipped_logs(zip_name, log_dir=None, logger=None, skip_files_pattern=r''):
    try:
        zipp_logs(zip_name=zip_name, log_dir=log_dir, logger=logger, skip_files_pattern=skip_files_pattern)
        yield zip_name
    finally:
        logger.info(f"removing {zip_name}")
        if os.path.isfile(zip_name):  # zipping may fail
            os.remove(zip_name)


def configure_logging_to_files(logging_level, log_dir, log_file, remove_old_logs, base_logger_name='ue_proxy'):
    global logging_path
    global log_basename
    global main_log_handler
    logging_path = log_dir
    log_basename = log_file[0:-4] if log_file.endswith(".log") else log_file
    if os.path.exists(logging_path) and remove_old_logs:
        _remove_logs(logs_directory=logging_path)

    with dynamic_propagation_logger():
        main_logger = logging.getLogger(base_logger_name)
    if main_logger.name not in active_dev_loggers:
        logging_loglevel = convert_logging_level(logging_level)
        log_formatter = UserKeysExtendedFormatter(["device_id"], FILE_FORMAT)

        if not os.path.exists(logging_path):
            os.makedirs(logging_path)

        main_logger.info(f'creating log file: {log_file}')
        my_handler = _create_main_log_handler(log_file, log_formatter, logging_loglevel)
        _add_logger_handler(logger=main_logger, handler=my_handler)
        main_log_handler = my_handler

        # always have debug logs for library debugging
        main_logger.info(f'creating debug log file: {log_file}.debug')
        log_formatter = UserKeysExtendedFormatter(["proxy_id", "layer"], FILE_FORMAT_PRX)
        dbg_handler = _create_debug_log_handler(log_file=log_basename, log_formatter=log_formatter)
        _add_logger_handler(logger=main_logger, handler=dbg_handler)

        active_dev_loggers.add(main_logger.name)


def configure_device_logger(device_id, base_logger_name='ue_proxy', create_log=False, create_raw_log=False, propagate=True):
    """Configure logger with file storing UEHandler connections log"""
    logger_name = f'{base_logger_name}.{device_id}'
    if logger_name not in active_dev_loggers:
        main_logger = logging.getLogger(base_logger_name)
        log_file_base = f"{log_basename}.{device_id}"
        with dynamic_propagation_logger():
            logger = logging.getLogger(logger_name)
        logger.propagate = propagate
        if create_log:
            log_lvl = main_log_handler.level if main_log_handler else logging.DEBUG
            logger.setLevel(logging.DEBUG)
            main_logger.info(f'creating log file: {log_file_base}.log')
            log_formatter = UserKeysExtendedFormatter(["proxy_id"], UE_FILE_FORMAT)
            file_hndl = _create_rotating_log_handler(log_file=f"{log_file_base}.log", log_formatter=log_formatter,
                                                     logging_loglevel=log_lvl)
            _add_logger_handler(logger=logger, handler=file_hndl)
        if create_raw_log:
            logger.setLevel(RAW_DATA)
            main_logger.info(f'creating raw log file: {log_file_base}.raw.log')
            logger.set_propagator(propagator=dont_propagate_raw_logrecords)
            log_formatter = UserKeysExtendedFormatter(["proxy_id"], RAWFILE_FORMAT)
            raw_file_hndl = _create_raw_data_log_handler(log_file=log_file_base, log_formatter=log_formatter)
            _add_logger_handler(logger=logger, handler=raw_file_hndl)
        active_dev_loggers.add(logger_name)
    else:
        logger = logging.getLogger(logger_name)
    return logger


def dont_propagate_raw_logrecords(record):
    if record.levelno == RAW_DATA:
        return False
    return True


def _create_main_log_handler(log_file, log_formatter, logging_loglevel):
    m_handler = _create_rotating_log_handler(log_file, log_formatter, logging_loglevel)
    return m_handler


def _create_debug_log_handler(log_file, log_formatter):
    dbg_handler = _create_rotating_log_handler(f"{log_file}.debug.log", log_formatter, logging.DEBUG)
    return dbg_handler


def only_raw_logrecords(record):
    if record.levelno == RAW_DATA:
        return 1
    return 0


def _create_raw_data_log_handler(log_file, log_formatter):
    # conn_formatter = MultilineWithDirectionFormatter(fmt="%(asctime)s.%(msecs)03d %(transfer_direction)s|%(message)s")
    raw_handler = _create_rotating_log_handler(f"{log_file}.raw.log",
                                               log_formatter,
                                               RAW_DATA,
                                               max_bytes=1 * 1024 * 1024)
    raw_handler.addFilter(only_raw_logrecords)
    return raw_handler


def _create_rotating_log_handler(log_file, log_formatter, logging_loglevel, mode='a', max_bytes=10 * 1024 * 1024):
    logfile_full_path = os.path.join(logging_path, log_file)
    rhandler = RotatingFileHandler(logfile_full_path, mode=mode, maxBytes=max_bytes, backupCount=1, encoding='utf-8')
    rhandler.setFormatter(log_formatter)
    rhandler.setLevel(logging_loglevel)
    active_log_files.add(logfile_full_path)
    return rhandler


def configure_debugging():
    global debug_console
    logging.basicConfig(level=RAW_DATA, format=CONSOLE_FORMAT)
    debug_console = True


def _create_console_handler(loglevel=logging.INFO, fmt=CONSOLE_FORMAT):
    cfh = logging.StreamHandler()
    cfh.setLevel(level=loglevel)
    cfh.setFormatter(logging.Formatter(fmt))
    return cfh
